function getScalenuTranslation(key, lang) {
    if (scalenuTranslations[lang] && scalenuTranslations[lang][key]) {
        return scalenuTranslations[lang][key];
    }
    if (scalenuTranslations.en && scalenuTranslations.en[key]) {
        return scalenuTranslations.en[key];
    }
    return null;
}

function applyScalenuTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.scalenut.')) {
            const translation = getScalenuTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyScalenuTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyScalenuTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyScalenuTranslations(currentLang);
}


